from collections import Counter
from typing import List

class Solution:
    def maxCardPairs(self, cards: List[str]) -> int:
        # Group cards by first letter and second letter
        first_group = Counter()
        for c in cards:
            first_group[c[0]] += 1

        # Maximum matching where pairs can share letters
        ans = 0
        counts = Counter(cards)

        # Exact duplicate pairs
        for card, cnt in list(counts.items()):
            ans += cnt // 2
            counts[card] %= 2

        # Match cards sharing the first letter
        by_first = Counter()
        for card, cnt in counts.items():
            if cnt > 0:
                by_first[card[0]] += cnt

        for ch, cnt in by_first.items():
            ans += cnt // 2

        return ans

#include <vector>
#include <string>
#include <unordered_map>

class Solution {
public:
    int maxCardPairs(std::vector<std::string>& cards) {
        std::unordered_map<std::string, int> counts;
        for (const auto& c : cards) counts[c]++;

        int ans = 0;
        for (auto& [card, cnt] : counts) {
            ans += cnt / 2;
            cnt %= 2;
        }

        std::unordered_map<char, int> by_first;
        for (const auto& [card, cnt] : counts) {
            if (cnt > 0) {
                by_first[card[0]] += cnt;
            }
        }
        for (const auto& [ch, cnt] : by_first) {
            ans += cnt / 2;
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int maxCardPairs(String[] cards) {
        Map<String, Integer> counts = new HashMap<>();
        for (String c : cards) {
            counts.put(c, counts.getOrDefault(c, 0) + 1);
        }

        int ans = 0;
        for (Map.Entry<String, Integer> entry : counts.entrySet()) {
            int cnt = entry.getValue();
            ans += cnt / 2;
            entry.setValue(cnt % 2);
        }

        Map<Character, Integer> byFirst = new HashMap<>();
        for (Map.Entry<String, Integer> entry : counts.entrySet()) {
            if (entry.getValue() > 0) {
                char ch = entry.getKey().charAt(0);
                byFirst.put(ch, byFirst.getOrDefault(ch, 0) + entry.getValue());
            }
        }
        for (int cnt : byFirst.values()) {
            ans += cnt / 2;
        }
        return ans;
    }
}

var maxCardPairs = function(cards) {
    const counts = new Map();
    for (const c of cards) {
        counts.set(c, (counts.get(c) || 0) + 1);
    }

    let ans = 0;
    for (const [card, cnt] of counts.entries()) {
        ans += Math.floor(cnt / 2);
        counts.set(card, cnt % 2);
    }

    const byFirst = new Map();
    for (const [card, cnt] of counts.entries()) {
        if (cnt > 0) {
            const ch = card[0];
            byFirst.set(ch, (byFirst.get(ch) || 0) + cnt);
        }
    }
    for (const cnt of byFirst.values()) {
        ans += Math.floor(cnt / 2);
    }
    return ans;
};
